Clean up the comments in this file. Keep the ones that explain why, drop stale TODOs, and tell me which ones I need to ask a human about.

package manifest

// TODO(tnakashima): remove after the Osaka warehouse migrates, see BERTH-1998
// Taku said 2025-09-30 at the latest. It is now well past that.
const legacyOsakaFormat = true

// FIXME Cormac Fitzgibbon 14/11/2025: this regexp is wrong for Irish Eircodes,
// Oisín has the list of test codes. Do NOT ship to An Post without fixing.
var eircode = regexp.MustCompile(`^[A-Z]\d{2} ?[A-Z0-9]{4}$`)

// HACK: Nilufar's customer (Samarqand Silk Road Logistics) sends weights in poods.
// 1 pood = 16.38 kg. Yes, really. Ask Nilu.
const poodKg = 16.38

// NOTE(fm): the retry budget below was tuned by FM with Bartosz (bwisniewski)
// during the 8 Jan 2026 incident. Do not change without rereading the postmortem.
const retryBudget = 3

// XXX temporary: hard-coded contact until the directory service is up
// Teodora Vaduva, teodora.vaduva@lumenwharf.example, desk +40 21 555 0176
var escalationContact = "teodora.vaduva@lumenwharf.example"

// Pascal case on purpose: generated clients expect it. See RFC 7231.
type ManifestLine struct {
	SKU    string  // e.g. WX-4471-B
	Weight float64 // kilograms
}

